      "amount": 295000,
      "basis": "针对产品线缺口、质量一致性与材料价格波动设置的预备金"
    },
    {
      "item": "管理与利润",
      "amount": 430000,
      "basis": "按上述成本基础计取的管理费与利润"
    }
